// seriesDirOf returns the library-relative series directory of rel (its
// parent; a bare file name is its own series dir, matching the scanner's
// series_relative_path stamp).
func seriesDirOf(rel string) string {
	for i := len(rel) - 1; i >= 0; i-- {
		if rel[i] == '/' {
			return rel[:i]
		}
	}
	return rel
}

// TestSeriesNameGrammar is the series name-grammar table, moved verbatim from
// the serial-parser plugin table (change serial boxes 1.1 + 1.2) into the
// shared package. Adapter-side season defaulting (0 → 1) stays with the
// adapters: package semantics are honest — a defaulted season is Season 0
// with SeasonExplicit false (rows the plugin pinned at season 1 / confidence
// 0.6 assert 0 / false here). Derived rows come from the real-collection
// shape inventory, titles and group names neutralized.
func TestSeriesNameGrammar(t *testing.T) {
	cases := []struct {
		name       string
		dirNameRaw string
		backing    string // "file" for a file-backed serial name, else "directory"
		wantTitle  string
		wantSeason int
		wantExpl   bool
	}{
		// Ground-truth rows.
		{name: "file-backed roman sequel suffix", dirNameRaw: "Black_Clover_II_[01].mkv", backing: "file", wantTitle: "Black Clover", wantSeason: 2, wantExpl: true},
		{name: "TV N marker", dirNameRaw: "Aria TV 1", wantTitle: "Aria", wantSeason: 1, wantExpl: true},
		{name: "standalone Sxx marker", dirNameRaw: "Black Clover S2", wantTitle: "Black Clover", wantSeason: 2, wantExpl: true},
		{name: "explicit S01 marker", dirNameRaw: "Show Name S01", wantTitle: "Show Name", wantSeason: 1, wantExpl: true},
		// Derived rows, neutralized.
		{name: "TV hyphen form", dirNameRaw: "Azure Harbor TV-2", wantTitle: "Azure Harbor", wantSeason: 2, wantExpl: true},
		{name: "Season N word form", dirNameRaw: "Crimson Vale Season 2", wantTitle: "Crimson Vale", wantSeason: 2, wantExpl: true},
		{name: "roman sequel folder", dirNameRaw: "Ivory Tower II", wantTitle: "Ivory Tower", wantSeason: 2, wantExpl: true},
		{name: "roman sequel folder VIII", dirNameRaw: "Quiet Meadow_VIII", wantTitle: "Quiet Meadow", wantSeason: 8, wantExpl: true},
		{name: "bracket-train-only folder falls back to the raw cleaned name", dirNameRaw: "[TV-1] [2023] [WEBRip] [1080p] [RUS + ENG] [Multi5-Subs]", wantTitle: "[TV-1] [2023] [WEBRip] [1080p] [RUS + ENG] [Multi5-Subs]", wantSeason: 0, wantExpl: false},
		{name: "trailing bare digit is not a season marker", dirNameRaw: "Title 0", wantTitle: "Title 0", wantSeason: 0, wantExpl: false},
		{name: "internal _3_ is not a season marker", dirNameRaw: "Title_3_The_End…", wantTitle: "Title 3 The End…", wantSeason: 0, wantExpl: false},
		// Ground-truth rows.
		{name: "dot-scape with release tags", dirNameRaw: "From.S02.WEBDL.720p.Rus.Eng", wantTitle: "From", wantSeason: 2, wantExpl: true},
		{name: "ordinal marker, dash group tag, bracket tags", dirNameRaw: "Mairimashita! Iruma-kun 4th Season - AniLiberty [WEB-DL 1080p]", wantTitle: "Mairimashita! Iruma-kun", wantSeason: 4, wantExpl: true},
		{name: "bracket tags strip, title kept", dirNameRaw: "Kimi ga Shinu made Koi wo Shitai [WEB-DL 1080p]", wantTitle: "Kimi ga Shinu made Koi wo Shitai", wantSeason: 0, wantExpl: false},
		{name: "paren year strips", dirNameRaw: "Bleach S04 (2008)", wantTitle: "Bleach", wantSeason: 4, wantExpl: true},
		{name: "bare year stays in the title", dirNameRaw: "Quiet Meadow 2022", wantTitle: "Quiet Meadow 2022", wantSeason: 0, wantExpl: false},
		{name: "multi-word dash segment preserved whole", dirNameRaw: "Demon Slayer - Kimetsu no Yaiba Entertainment District Arc", wantTitle: "Demon Slayer - Kimetsu no Yaiba Entertainment District Arc", wantSeason: 0, wantExpl: false},
		// Derived rows, neutralized.
		{name: "leading group bracket + rip combinator", dirNameRaw: "[Bluewave] Azure Harbor [BDRip 1080p x265 FLAC]", wantTitle: "Azure Harbor", wantSeason: 0, wantExpl: false},
		{name: "multi-bracket with source tag and acronym", dirNameRaw: "Crimson Vale [WEB-DL 1080p] [KTX]", wantTitle: "Crimson Vale", wantSeason: 0, wantExpl: false},
		{name: "cyrillic title + bracket", dirNameRaw: "Необычная гавань [WEB-DL 1080p]", wantTitle: "Необычная гавань", wantSeason: 0, wantExpl: false},
		{name: "trailing space normalizes", dirNameRaw: "Azure Harbor - Heaven's Feel ", wantTitle: "Azure Harbor - Heaven's Feel", wantSeason: 0, wantExpl: false},
		{name: "double space normalizes", dirNameRaw: "Azure Harbor  Unlimited Blade Works", wantTitle: "Azure Harbor Unlimited Blade Works", wantSeason: 0, wantExpl: false},
		{name: "non-leading paren matching no mask is preserved", dirNameRaw: "Title_(Shiro)", wantTitle: "Title (Shiro)", wantSeason: 0, wantExpl: false},
		// Group-tag shape pins: the trailing CamelCase tag strips after ANY
		// separator (space, dot, underscore), not only after a dash.
		{name: "underscore-separated group tag strips", dirNameRaw: "Quiet_Meadow_FulL", wantTitle: "Quiet Meadow", wantSeason: 0, wantExpl: false},
		{name: "space-separated group tag strips", dirNameRaw: "Ivory Tower FulL", wantTitle: "Ivory Tower", wantSeason: 0, wantExpl: false},
		{name: "dot-separated group tag strips", dirNameRaw: "Quiet.Meadow.FulL", wantTitle: "Quiet Meadow", wantSeason: 0, wantExpl: false},
		// Canonical row (unified-parser): the whole-token 720i joins the
		// resolution table once and strips from the title everywhere.
		{name: "whole-token 720i strips from the title", dirNameRaw: "Show 720i", wantTitle: "Show", wantSeason: 0, wantExpl: false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			_ = tc.backing // a file-backed name differs only by its extension; ParseName strips it
			r := ParseName(tc.dirNameRaw)
			if r.Title != tc.wantTitle {
				t.Fatalf("title = %q, want %q", r.Title, tc.wantTitle)
			}
			if r.Season != tc.wantSeason {
				t.Fatalf("season = %d, want %d", r.Season, tc.wantSeason)
			}
			if r.SeasonExplicit != tc.wantExpl {
				t.Fatalf("seasonExplicit = %v, want %v", r.SeasonExplicit, tc.wantExpl)
			}
			if r.Episode != 0 {
				t.Fatalf("series name carries no episode, got %d", r.Episode)
			}
		})
	}
}

// TestEpisodeNameGrammar is the episode-grammar table, moved verbatim from the
// serial-parser plugin table (change serial box 1.3) into the shared package.
// Package semantics are honest: a season defaulted by the adapter (0 → 1) is
// Season 0 here, and a numberless filename is Episode 0 rather than !ok.
// Derived rows come from the real-collection shape inventory, neutralized.
func TestEpisodeNameGrammar(t *testing.T) {
	cases := []struct {
		name        string
		rel         string
		wantSeason  int
		wantEpisode int
	}{
		// Ground-truth rows.
		{name: "bracket number with filename ordinal marker", rel: "Mairimashita_Iruma-kun_4th_Season/Mairimashita_Iruma-kun_4th_Season_[01].mkv", wantSeason: 4, wantEpisode: 1},
		{name: "dash number after rip bracket", rel: "Kimi ga Shinu made Koi wo Shitai/Kimi ga Shinu made Koi wo Shitai - 01 [1080p AVC AAC].mkv", wantSeason: 0, wantEpisode: 1},
		{name: "cyrillic marker with TV series marker", rel: "Aria TV 1/[01] Aria TV 1 01 серия.mkv", wantSeason: 1, wantEpisode: 1},
		{name: "group bracket and trailing dash number", rel: "Kimetsu no Yaiba - Yuukaku Hen/[Erai-raws] Kimetsu no Yaiba - Yuukaku Hen - 01.mkv", wantSeason: 0, wantEpisode: 1},
		{name: "numberless filename has no episode", rel: "Show/Feature.mkv"},
		{name: "bare zero is no episode number", rel: "Show/Title 0.mkv"},
		{name: "zero edge bracket is no episode number", rel: "Show/[00] Title.mkv"},
		{name: "zero cyrillic marker is no episode number", rel: "Show/Title 0 серия.mkv"},
		// Derived rows, neutralized.
		{name: "leading bracket number with cyrillic marker", rel: "Azure Harbor/[01] Azure Harbor 01 серия.mkv", wantSeason: 0, wantEpisode: 1},
		{name: "roman sequel in the episode stem", rel: "Azure Harbor II/[Bluewave] Azure Harbor II 01 [BDrip 1920x1080 x264 FLAC].mkv", wantSeason: 2, wantEpisode: 1},
		{name: "word-form marker in the episode stem", rel: "Crimson Vale Season 2/Crimson Vale Season 2 - 01 [1080p].mkv", wantSeason: 2, wantEpisode: 1},
		{name: "no marker anywhere leaves the season absent", rel: "Ivory Tower/[Bluewave] Ivory Tower - 01 [BDRip 1080p x265 FLAC].mkv", wantSeason: 0, wantEpisode: 1},
		{name: "season falls back to the series directory marker", rel: "Azure Harbor TV-2/[Bluewave] Azure Harbor - 05 [BDRip 1080p].mkv", wantSeason: 2, wantEpisode: 5},
		{name: "unbracketed resolution token is not an episode number", rel: "Show/Show - 01 360p.mkv", wantSeason: 0, wantEpisode: 1},
		// Canonical rows (unified-parser): the trailing-decoration bracket is
		// an episode candidate wherever it occurs (rightmost wins), and the
		// whole-token 720i is a resolution, never an episode number.
		{name: "trailing-decoration bracket after roman sequel", rel: "Show_Name_II/Show_Name_II_[01]_[HEVC].mkv", wantSeason: 2, wantEpisode: 1},
		{name: "whole-token 720i is no episode number", rel: "Show/Title 720i.mkv", wantSeason: 0, wantEpisode: 0},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			r := ParseEpisodeName(tc.rel, seriesDirOf(tc.rel))
			if r.Episode != tc.wantEpisode {
				t.Fatalf("episode = %d, want %d", r.Episode, tc.wantEpisode)
			}
			if r.Season != tc.wantSeason {
				t.Fatalf("season = %d, want %d", r.Season, tc.wantSeason)
			}
			if tc.wantSeason > 0 && !r.SeasonExplicit {
				t.Fatalf("season %d must be explicit", r.Season)
			}
		})
	}
}

// TestFilmNameParse pins the degenerate film case: a name with no season and
// no episode parses to title plus release fields, Season 0, Episode 0.
func TestFilmNameParse(t *testing.T) {
	cases := []struct {
		name       string
		raw        string
		wantTitle  string
		wantYear   int
		wantRes    string
		wantSource string
		wantCodecs []string
	}{
		{name: "tagged film degenerate case", raw: "Blue Horizon (2019) [WEB-DL 1080p x264] - FanGroup", wantTitle: "Blue Horizon", wantYear: 2019, wantRes: "1080p", wantSource: "web-dl", wantCodecs: []string{"x264"}},
		{name: "dot-scape film with no season or episode", raw: "Some.Movie.2020.1080p.WEB-DL.x264", wantTitle: "Some Movie 2020", wantYear: 2020, wantRes: "1080p", wantSource: "web-dl", wantCodecs: []string{"x264"}},
		{name: "hyphenated title text after a consumed tag keeps whole", raw: "Some.Movie.1080p.Spider-Man.mkv", wantTitle: "Some Movie Spider-Man", wantYear: 0, wantRes: "1080p", wantSource: "", wantCodecs: nil},
		{name: "amzn source and dot-form codec strip from the real film name", raw: "Chainsaw.Man.The.Movie.Reze.Arc.2025.1080p.AMZN.WEB-DL.H.264-EniaHD.mkv", wantTitle: "Chainsaw Man The Movie Reze Arc 2025", wantYear: 2025, wantRes: "1080p", wantSource: "web-dl", wantCodecs: []string{"h.264"}},
		{name: "dash-form group token strips after a consumed tag", raw: "Demon.Slayer.Kimetsu.No.Yaiba.Infinity.Castle.1080p.CR-Cassu.mkv", wantTitle: "Demon Slayer Kimetsu No Yaiba Infinity Castle", wantYear: 0, wantRes: "1080p", wantSource: "", wantCodecs: nil},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			r := ParseName(tc.raw)
			if r.Title != tc.wantTitle {
				t.Fatalf("title = %q, want %q", r.Title, tc.wantTitle)
			}
			if r.Season != 0 || r.SeasonExplicit {
				t.Fatalf("film case must carry no season, got season %d explicit %v", r.Season, r.SeasonExplicit)
			}
			if r.Episode != 0 || r.EpisodeEnd != 0 {
				t.Fatalf("film case must carry no episode, got %d..%d", r.Episode, r.EpisodeEnd)
			}
			if r.Year != tc.wantYear {
				t.Fatalf("year = %d, want %d", r.Year, tc.wantYear)
			}
			if r.Resolution != tc.wantRes || r.Source != tc.wantSource {
				t.Fatalf("resolution/source = %q/%q, want %q/%q", r.Resolution, r.Source, tc.wantRes, tc.wantSource)
			}
			if !reflect.DeepEqual(r.Codecs, tc.wantCodecs) {
				t.Fatalf("codecs = %v, want %v", r.Codecs, tc.wantCodecs)
			}
		})
	}
}

// TestEmissionFields pins the Result honesty rules: singular roles last-wins,
// lists in token order, Season 0 + SeasonExplicit false with no marker, a
// below-1 episode absent, and absent fields absent — never zeroed stand-ins.
func TestEmissionFields(t *testing.T) {
	t.Run("singular roles last-wins", func(t *testing.T) {
		r := ParseName("Quiet Meadow 720p WEBRip 1080p WEB-DL")
		if r.Resolution != "1080p" {
			t.Fatalf("resolution = %q, want the last token 1080p", r.Resolution)
		}
		if r.Source != "web-dl" {
			t.Fatalf("source = %q, want the last token web-dl", r.Source)
		}
	})
	t.Run("lists keep token order", func(t *testing.T) {
		r := ParseName("Show [x264 AAC FLAC] Rus Eng")
		if want := []string{"x264", "aac", "flac"}; !reflect.DeepEqual(r.Codecs, want) {
			t.Fatalf("codecs = %v, want %v", r.Codecs, want)
		}
		if want := []string{"rus", "eng"}; !reflect.DeepEqual(r.Languages, want) {
			t.Fatalf("languages = %v, want %v", r.Languages, want)
		}
	})
	t.Run("season honesty and absent fields", func(t *testing.T) {
		r := ParseName("Just A Movie")
		if r.Season != 0 || r.SeasonExplicit {
			t.Fatalf("season = %d explicit %v, want 0/false (the adapter owns its default)", r.Season, r.SeasonExplicit)
		}
		if r.Episode != 0 || r.EpisodeEnd != 0 {
			t.Fatalf("episode = %d..%d, want 0..0", r.Episode, r.EpisodeEnd)
		}
		if r.Resolution != "" || r.Source != "" || r.Year != 0 {
			t.Fatalf("absent release fields must stay absent, got %+v", r)
		}
		if len(r.Codecs) != 0 || len(r.Languages) != 0 {
			t.Fatalf("absent lists must stay empty, got %+v", r)
		}
	})
	t.Run("below-1 episode is absent", func(t *testing.T) {
		for _, rel := range []string{"Show/[00] Title.mkv", "Show/Title 0.mkv", "Show/Title 0 серия.mkv"} {
			if r := ParseEpisodeName(rel, seriesDirOf(rel)); r.Episode != 0 {
				t.Fatalf("%s: episode = %d, want 0", rel, r.Episode)
			}
		}
	})
	t.Run("explicit season and episode span", func(t *testing.T) {
		r := ParseEpisodeName("Show/Show.S02E10E11.1080p.mkv", "Show")
		if r.Season != 2 || !r.SeasonExplicit {
			t.Fatalf("season = %d explicit %v, want 2/true", r.Season, r.SeasonExplicit)
		}
		if r.Episode != 10 || r.EpisodeEnd != 11 {
			t.Fatalf("episode span = %d..%d, want 10..11", r.Episode, r.EpisodeEnd)
		}
		if r.Resolution != "1080p" {
			t.Fatalf("resolution = %q, want 1080p", r.Resolution)
		}
		if r.Title != "Show" {
			t.Fatalf("title = %q, want Show", r.Title)
		}
	})
	t.Run("episode emission beside the season marker", func(t *testing.T) {
		r := ParseEpisodeName("Show II - 01 [WEBRip 1080p HEVC] - FanGroup", "")
		if r.Title != "Show" {
			t.Fatalf("title = %q, want Show", r.Title)
		}
		if r.Season != 2 || !r.SeasonExplicit {
			t.Fatalf("season = %d explicit %v, want 2/true", r.Season, r.SeasonExplicit)
		}
		if r.Episode != 1 {
			t.Fatalf("episode = %d, want 1", r.Episode)
		}
		if r.Source != "webrip" || r.Resolution != "1080p" {
			t.Fatalf("source/resolution = %q/%q, want webrip/1080p", r.Source, r.Resolution)
		}
		if want := []string{"hevc"}; !reflect.DeepEqual(r.Codecs, want) {
			t.Fatalf("codecs = %v, want %v", r.Codecs, want)
		}
	})
}
